<?php require '../common.php';startpage('Hotel Room Booking');nav('<a href="index.php">Rooms</a><a href="history.php">Booking history</a><a href="admin.php">Admin</a>');$rs=$conn->query('SELECT * FROM rooms');?><p>Choose a room type and book your dates. Payment gateway/email are not connected in this lab demo.</p><table><tr><th>Room type</th><th>Price per night</th><th>Quantity</th><th>Description</th><th>Book</th></tr><?php while($r=$rs->fetch_assoc()):?><tr><td><?=e($r['room_type'])?></td><td>₹<?=$r['price']?></td><td><?=$r['quantity']?></td><td><?=e($r['description'])?></td><td><a href="book.php?id=<?=$r['id']?>">Book</a></td></tr><?php endwhile;?></table><?php endpage();?>